import { resolve } from 'node:path';
import { pathToFileURL } from 'node:url';

function isNonnegativeSafeInteger(value) {
  return Number.isSafeInteger(value) && value >= 0;
}

function validateOptions(options) {
  if (options === null || typeof options !== 'object' || Array.isArray(options)) {
    throw new Error('options must be a non-null, non-array object');
  }

  const { attempt, elapsedMs, baseMs, maxDelayMs, budgetMs, retryAfterMs, retryable } = options;

  if (!Number.isSafeInteger(attempt) || attempt <= 0) {
    throw new Error('attempt must be a positive safe integer');
  }
  if (!isNonnegativeSafeInteger(elapsedMs)) {
    throw new Error('elapsedMs must be a nonnegative safe integer');
  }
  if (!isNonnegativeSafeInteger(baseMs)) {
    throw new Error('baseMs must be a nonnegative safe integer');
  }
  if (!isNonnegativeSafeInteger(maxDelayMs)) {
    throw new Error('maxDelayMs must be a nonnegative safe integer');
  }
  if (!isNonnegativeSafeInteger(budgetMs)) {
    throw new Error('budgetMs must be a nonnegative safe integer');
  }
  if (retryAfterMs !== null && !isNonnegativeSafeInteger(retryAfterMs)) {
    throw new Error('retryAfterMs must be null or a nonnegative safe integer');
  }
  if (typeof retryable !== 'boolean') {
    throw new Error('retryable must be a boolean');
  }

  return { attempt, elapsedMs, baseMs, maxDelayMs, budgetMs, retryAfterMs, retryable };
}

function cappedExponentialDelay(baseMs, maxDelayMs, attempt) {
  if (baseMs === 0 || maxDelayMs === 0) {
    return 0;
  }

  const exponent = attempt - 1;
  // 2 ** 53 is greater than every safe integer, so any positive base is capped.
  if (exponent >= 53) {
    return maxDelayMs;
  }

  const factor = 2 ** exponent;
  return baseMs > Math.floor(maxDelayMs / factor)
    ? maxDelayMs
    : baseMs * factor;
}

export function nextRetry(options) {
  const { attempt, elapsedMs, baseMs, maxDelayMs, budgetMs, retryAfterMs, retryable } =
    validateOptions(options);

  if (!retryable) {
    return { retry: false, delayMs: null, reason: 'non-retryable' };
  }

  const exponentialDelay = cappedExponentialDelay(baseMs, maxDelayMs, attempt);
  const delayMs = retryAfterMs === null
    ? exponentialDelay
    : Math.max(exponentialDelay, retryAfterMs);

  if (elapsedMs > budgetMs || delayMs > budgetMs - elapsedMs) {
    return { retry: false, delayMs: null, reason: 'budget-exhausted' };
  }

  return { retry: true, delayMs, reason: 'scheduled' };
}

function runCli(argv) {
  if (argv.length !== 3) {
    throw new Error('usage: node retry-budget.js INPUT_JSON_FILE');
  }

  let options;
  try {
    options = JSON.parse(readFileSync(argv[2], 'utf8'));
  } catch (error) {
    throw new Error(`cannot read valid JSON input: ${error.message}`);
  }

  process.stdout.write(`${JSON.stringify(nextRetry(options))}\n`);
}

if (process.argv[1] && import.meta.url === pathToFileURL(resolve(process.argv[1])).href) {
  try {
    runCli(process.argv);
  } catch (error) {
    process.stderr.write(`${error instanceof Error ? error.message : String(error)}\n`);
    process.exitCode = 2;
  }
